from ortools.linear_solver import pywraplp
import json

def main():
    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        return

    num_aircraft = 20
    num_runways = 3

    earliest = [75, 157, 134, 103, 201, 95, 185, 98, 117, 117, 132, 114, 261, 250, 214, 310, 269, 237, 144, 151]
    target = [82, 197, 160, 117, 261, 106, 229, 108, 132, 130, 149, 126, 336, 316, 258, 409, 338, 287, 160, 169]
    latest = [486, 628, 561, 565, 735, 524, 664, 523, 578, 569, 615, 551, 834, 790, 688, 967, 818, 726, 607, 624]
    penalty_rate = [30, 10, 10, 30, 10, 30, 10, 30, 30, 30, 30, 30, 10, 10, 10, 10, 10, 10, 30, 30]

    large_set = {0, 1, 4, 6, 12, 13, 14, 15, 16, 17}
    small_set = {2, 3, 5, 7, 8, 9, 10, 11, 18, 19}

    sep_LL = 3
    sep_SS = 8
    sep_mixed = 15

    t = []
    for i in range(num_aircraft):
        t.append(solver.NumVar(earliest[i], latest[i], f't[{i}]'))

    assign = []
    for i in range(num_aircraft):
        assign_row = []
        for r in range(num_runways):
            assign_row.append(solver.BoolVar(f'assign[{i},{r}]'))
        assign.append(assign_row)

    dev = []
    for i in range(num_aircraft):
        dev.append(solver.NumVar(0, solver.infinity(), f'dev[{i}]'))

    for i in range(num_aircraft):
        solver.Add(sum(assign[i][r] for r in range(num_runways)) == 1)

    for i in range(num_aircraft):
        solver.Add(dev[i] >= t[i] - target[i])
        solver.Add(dev[i] >= target[i] - t[i])

    M = 10000

    for i in range(num_aircraft):
        for j in range(i + 1, num_aircraft):
            if i in large_set and j in large_set:
                sep = sep_LL
            elif i in small_set and j in small_set:
                sep = sep_SS
            else:
                sep = sep_mixed

            for r in range(num_runways):
                both_on_r = solver.BoolVar(f'both_on_r[{i},{j},{r}]')

                solver.Add(both_on_r <= assign[i][r])
                solver.Add(both_on_r <= assign[j][r])
                solver.Add(both_on_r >= assign[i][r] + assign[j][r] - 1)

                i_before_j = solver.BoolVar(f'i_before_j[{i},{j},{r}]')
                j_before_i = solver.BoolVar(f'j_before_i[{i},{j},{r}]')

                solver.Add(i_before_j + j_before_i >= both_on_r)

                solver.Add(t[j] >= t[i] + sep - M * (1 - i_before_j))

                solver.Add(t[i] >= t[j] + sep - M * (1 - j_before_i))

    objective = solver.Sum(penalty_rate[i] * dev[i] for i in range(num_aircraft))
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        landing_times = [round(t[i].solution_value()) for i in range(num_aircraft)]
        runways = []
        for i in range(num_aircraft):
            for r in range(num_runways):
                if assign[i][r].solution_value() > 0.5:
                    runways.append(r + 1)
                    break
        total_penalty = round(solver.Objective().Value())
    else:
        landing_times = []
        runways = []
        total_penalty = -1

    print(json.dumps({
        "landing_times": landing_times,
        "runways": runways,
        "total_penalty": total_penalty
    }))

if __name__ == '__main__':
    main()
